"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[254],{254(e,i,t){t.d(i,{content:()=>o,description:()=>n,keywords:()=>r,title:()=>s});t(5043);var a=t(579);const s="Histoire de WhimsyLabs : De d\xe9buts modestes \xe0 BETT 2025",n="Comment WhimsyLabs aborde les d\xe9fis STEM avec des laboratoires simul\xe9s, des partenariats impactants et une innovation prim\xe9e BETT 2025.",r=["histoire laboratoire virtuel","BETT 2025 gagnant","innovation \xe9ducation STEM","solutions \xe9ducation COVID-19","moteur physique propri\xe9taire","histoire fondation WhimsyLabs","Marisa French fondatrice","d\xe9veloppement laboratoire virtuel","parcours startup EdTech"],o=(0,a.jsxs)("div",{children:[(0,a.jsx)("p",{children:"Whimsylabs a \xe9t\xe9 initialement cr\xe9\xe9 en 2020 par Marisa French vers la fin de son doctorat en physique, juste au moment o\xf9 la pand\xe9mie commen\xe7ait \xe0 frapper. L'impact d\xe9vastateur du COVID-19, qui a ferm\xe9 les environnements de laboratoire traditionnels, a laiss\xe9 de nombreux \xe9tudiants sans acc\xe8s \xe0 l'\xe9ducation scientifique pratique pendant des ann\xe9es. Ceci, coupl\xe9 avec le d\xe9clin des classements STEM du Royaume-Uni, le Royaume-Uni chutant \xe0 la 15e place dans les classements scientifiques du Programme pour l'\xe9valuation internationale des \xe9tudiants (PISA) de l'OCDE, a mis en \xe9vidence une crise pour l'\xe9ducation britannique qui semblait personnelle, car Marisa avait \xe9t\xe9 inspir\xe9e \xe0 poursuivre la science gr\xe2ce aux travaux pratiques qu'elle avait v\xe9cus au lyc\xe9e."}),(0,a.jsx)("p",{children:"Pouss\xe9e par le d\xe9sir de cr\xe9er un changement significatif, Marisa a exploit\xe9 ses comp\xe9tences en simulation et en jeux pour d\xe9velopper un laboratoire virtuel sandbox enti\xe8rement simul\xe9. La recherche d\xe9montre que les environnements d'apprentissage bas\xe9s sur la simulation peuvent am\xe9liorer significativement l'engagement des \xe9tudiants et les r\xe9sultats d'apprentissage, particuli\xe8rement dans les domaines STEM o\xf9 l'exp\xe9rimentation pratique est cruciale. Ce laboratoire a \xe9t\xe9 con\xe7u pour \xeatre un environnement s\xfbr, accessible et engageant pour l'apprentissage pratique, sans les risques ou les co\xfbts associ\xe9s aux laboratoires traditionnels. L'objectif \xe9tait simple ; cr\xe9er un laboratoire virtuel qui capture enti\xe8rement le plaisir qu'elle avait v\xe9cu dans ses laboratoires scolaires, et qui pourrait \xeatre utilis\xe9 par n'importe qui, n'importe o\xf9, \xe0 tout moment."}),(0,a.jsx)("img",{src:"/images/oldLab.png",alt:"Premi\xe8re maquette de laboratoire",className:"rounded shadow center limited-size"}),(0,a.jsx)("p",{className:"caption",children:"La premi\xe8re maquette de laboratoire : Un prototype simple pour conceptualiser la vision de Whimsylabs."}),(0,a.jsx)("p",{children:"Le voyage a commenc\xe9 modestement avec une maquette de laboratoire rudimentaire qui servait \xe0 tester les id\xe9es de codage initiales. D\xe8s le d\xe9but, le r\xeave d'un laboratoire virtuel unifi\xe9 \xe9tait clair, mais le chemin pour le r\xe9aliser l'\xe9tait moins. Avec les simulations acad\xe9miques comme fondation, la premi\xe8re it\xe9ration du laboratoire \xe9tait un prototype simple qui a pos\xe9 les bases pour tester les id\xe9es et affiner la vision. Cependant, comme la plupart des simulations acad\xe9miques utilisent des superordinateurs et prennent des mois \xe0 fonctionner, le d\xe9fi \xe9tait de faire fonctionner les simulations en temps r\xe9el sur une plateforme VR sur mesure."}),(0,a.jsx)("p",{children:"La plupart du travail a \xe9t\xe9 fait pour affiner ces \xe9quations pour qu'elles fonctionnent en temps r\xe9el, tout en produisant des r\xe9sultats r\xe9alistes. Le premier laboratoire \xe9tait purement une preuve de concept, montrant que les simulations pouvaient \xeatre ex\xe9cut\xe9es en temps r\xe9el, et qu'elles pouvaient \xeatre interagies de mani\xe8re significative. Les \xe9tudes en \xe9ducation de physique computationnelle soulignent l'importance de l'interaction en temps r\xe9el pour la compr\xe9hension conceptuelle, car les commentaires imm\xe9diats aident les \xe9tudiants \xe0 connecter les concepts th\xe9oriques avec les ph\xe9nom\xe8nes observables."}),(0,a.jsx)("p",{children:"\xc0 cette \xe9poque, Whimsylabs a attir\xe9 l'attention de l'Universit\xe9 d'\xc9dimbourg gr\xe2ce \xe0 notre travail r\xe9volutionnaire en simulations et nos objectifs ambitieux ax\xe9s sur l'impact, s\xe9curisant des places dans leurs programmes d'incubation prestigieux et remportant l'Acc\xe9l\xe9rateur d'\xc9t\xe9. De ces victoires et reconnaissances, nous avons pu s\xe9curiser notre premier financement pour construire une plateforme combo VR/web sur mesure, et recruter notre deuxi\xe8me fondateur pour aider \xe0 construire le laboratoire ; un docteur en chimie avec des ann\xe9es d'exp\xe9rience en \xe9ducation et formation pour l'industrie chimique."}),(0,a.jsx)("img",{src:"/images/testLab.png",alt:"Deuxi\xe8me laboratoire de test technique",className:"rounded shadow center limited-size"}),(0,a.jsx)("p",{className:"caption",children:"Le deuxi\xe8me laboratoire : Un terrain d'essai pour les technologies de simulation avanc\xe9es."}),(0,a.jsx)("p",{children:"Le deuxi\xe8me laboratoire a \xe9t\xe9 construit pour voir comment nous pouvions faire en sorte que le laboratoire ressemble plus \xe0 un vrai laboratoire, et moins \xe0 un jeu vid\xe9o. C'\xe9tait la premi\xe8re fois que nous devions consid\xe9rer comment le laboratoire serait utilis\xe9 dans un v\xe9ritable environnement \xe9ducatif pour enseigner les mouvements et actions d'un laboratoire. Cette ph\xe9nom\xe9nologie du laboratoire s'est r\xe9v\xe9l\xe9e cruciale pour que les \xe9tudiants commencent \xe0 construire la m\xe9moire musculaire n\xe9cessaire pour effectuer ces proc\xe9dures dans la vraie vie, avec des choses comme la physique des liquides et les interactions physiques r\xe9alistes n\xe9cessaires pour capturer la sensation d'\xeatre dans un laboratoire. La recherche en cognition incarn\xe9e d\xe9montre que les mouvements physiques et les gestes am\xe9liorent significativement l'apprentissage et la r\xe9tention dans les contextes scientifiques."}),(0,a.jsx)("p",{children:"Le deuxi\xe8me laboratoire a \xe9t\xe9 un succ\xe8s, et nous avons pu contacter les \xe9coles pour tester le laboratoire dans un v\xe9ritable environnement \xe9ducatif. Les commentaires ont \xe9t\xe9 extr\xeamement positifs, avec les \xe9tudiants et enseignants louant le laboratoire pour son r\xe9alisme et sa facilit\xe9 d'utilisation. C'\xe9tait une \xe9tape critique dans le d\xe9veloppement du laboratoire, car cela montrait que le laboratoire pouvait \xeatre utilis\xe9 dans un v\xe9ritable environnement \xe9ducatif, et qu'il pouvait \xeatre un outil pr\xe9cieux pour l'enseignement et l'apprentissage. Il n'y avait qu'un seul probl\xe8me : le laboratoire \xe9tait laid."}),(0,a.jsx)("img",{src:"/images/finalLab.png",alt:"Conception finale du laboratoire",className:"rounded shadow center limited-size"}),(0,a.jsx)("p",{className:"caption",children:"Le laboratoire final : Un m\xe9lange de technologie de pointe et d'un design accueillant qui se d\xe9marque."}),(0,a.jsx)("p",{children:"Avec cela \xe0 l'esprit, nous nous sommes mis \xe0 redessiner compl\xe8tement le laboratoire \xe0 partir de z\xe9ro. Cependant, en raison de la puissance limit\xe9e des casques VR et du co\xfbt de traitement des simulations avanc\xe9es, il y avait peu de place pour refl\xe9ter un r\xe9alisme de haute fid\xe9lit\xe9. Une autre consid\xe9ration \xe9tait la large gamme d'\xe2ges qui utiliseraient le laboratoire, de 5 \xe0 18+, et le besoin de rendre le laboratoire accessible \xe0 tous. Le choix de direction \xe9tait difficile, mais \xe0 la fin nous avons \xe9t\xe9 guid\xe9s par l'un de nos d\xe9sirs originaux que le laboratoire soit un lieu d'\xe9merveillement et d'exploration, et qu'il devrait \xeatre un endroit o\xf9 les \xe9tudiants veulent revenir. La recherche en psychologie \xe9ducative souligne l'importance de la motivation intrins\xe8que et de l'apprentissage guid\xe9 par la curiosit\xe9 dans l'\xe9ducation STEM. C'est \xe0 cette \xe9poque que nous avons adopt\xe9 notre Whimsycat comme notre logo et mascotte, une ic\xf4ne unique dans l'espace des laboratoires virtuels, encapsulant la curiosit\xe9 et l'\xe9merveillement que nous voulions inspirer chez nos \xe9tudiants."}),(0,a.jsx)("p",{children:"La conception finale du laboratoire \xe9tait un m\xe9lange de technologie de pointe et d'un design accueillant qui se d\xe9marque dans l'espace edtech encombr\xe9. Ce laboratoire, notre laboratoire phare actuel, \xe9tait maintenant un environnement virtuel enti\xe8rement r\xe9alis\xe9 qui offrait une large gamme d'exp\xe9riences et de simulations, \xe0 travers la Chimie, la Physique et la Biologie. En utilisant ce laboratoire, nous avons pu entrer dans le prestigieux Converge Challenge, une comp\xe9tition pour les meilleures nouvelles entreprises en \xc9cosse, et s\xe9curiser une place en finale sous la cat\xe9gorie Create Change, o\xf9 nous avons termin\xe9 deuxi\xe8me parmi toutes les entreprises d'\xc9cosse."}),(0,a.jsx)("p",{children:"Gr\xe2ce \xe0 notre victoire \xe0 Converge, nous avons s\xe9curis\xe9 les fonds pour assister \xe0 BETT UK et amener nos innovations sur une sc\xe8ne mondiale. Les commentaires des \xe9tudiants et \xe9ducateurs ont \xe9t\xe9 extr\xeamement positifs, beaucoup soulignant comment la plateforme transforme l'\xe9ducation STEM. De plus, l'approche innovante de Whimsylabs n'\xe9tait pas pass\xe9e inaper\xe7ue. La plateforme a \xe9t\xe9 reconnue par l'Epping Forest Schools Partnership Trust dans le cadre du Kids Judge Bett, o\xf9 les \xe9l\xe8ves ont nomm\xe9 Whimsylabs pour leur utilisation de laboratoires virtuels pour enseigner aux \xe9tudiants les environnements de laboratoire, tout en fournissant un outil puissant pour la durabilit\xe9. Cette reconnaissance souligne le pouvoir de notre mission d'inspirer la prochaine g\xe9n\xe9ration de leaders STEM."}),(0,a.jsx)("p",{children:"Bien que Whimsylabs ait d\xe9velopp\xe9 discr\xe8tement sa technologie au cours des derni\xe8res ann\xe9es, seulement chuchot\xe9 parmi quelques \xe9coles pilotes, nous sommes maintenant pr\xeats \xe0 faire du bruit et \xe0 \xeatre bruyants au sujet de notre solution r\xe9volutionnaire. Avec une base solide, une \xe9quipe en croissance et un historique prouv\xe9 d'innovation, Whimsylabs est pr\xeat \xe0 transformer l'\xe9ducation scientifique et inspirer la prochaine g\xe9n\xe9ration de leaders STEM tout en restant fid\xe8le \xe0 nos valeurs fondamentales. Fournir un laboratoire sandbox qui capture la physicalit\xe9 de la r\xe9alisation d'exp\xe9riences, capturer le plaisir et l'\xe9merveillement de la science, et d\xe9mocratiser l'acc\xe8s \xe0 la technologie d'\xe9ducation scientifique premium pour toutes les institutions du monde entier."})]})}}]);
